  'careers.roles.hosts.title': 'Hos dan Penyampai Siaran Langsung',
  'careers.roles.hosts.description': 'Untuk individu yang yakin di hadapan kamera, menarik, bertanggungjawab dan mampu menerangkan produk atau topik dengan jelas.',
  'careers.roles.editors.title': 'Penyunting Video dan Pencipta Kandungan',
  'careers.roles.editors.description': 'Untuk pencipta yang berpengalaman dengan YouTube, podcast, TikTok, Instagram Reels dan YouTube Shorts.',
  'careers.roles.producers.title': 'Penerbit dan Operasi Studio',
  'careers.roles.producers.description': 'Untuk ahli pasukan yang boleh mengurus jadual rakaman, siaran langsung, tetamu, peralatan dan aliran kerja penerbitan.',
  'careers.roles.ai.title': 'Kandungan AI dan Teknologi Kreatif',
  'careers.roles.ai.description': 'Untuk pereka, pencipta AI, pakar prompt, pembangun watak maya dan ahli teknologi kreatif.',
